4	//  Translated from W2jet/atree.f
5	//  Author: R.K. Ellis, July 1998.
6	//  The basic process is atreepp: amplitude for
7	//    q-(p4)+Q(-p2)+l-(-p5) --> q+(p1)+Q-(p3)+l+(p6)
8	//  All outgoing particles are right-handed, except Q(p3) which is left-handed.
9	//  All tree amplitudes divided by im wrt to BDKW paper.
10	//  Implementation of BDKW Eq.(3.10).
11	
12	#include "atree.hpp"
13	#include <W1jet.hpp>
14	#include <mxpart_mod.hpp>
15	#include <sprods_com_mod.hpp>
16	#include <complex>
17	
18	using namespace mxpart_mod;
19	using namespace sprods_com_mod;
20	
21	std::complex<double> atree(const char* st, int j1, int j2, int j3, int j4, int j5, int j6,
22	                           FArray2D<std::complex<double>>& za,
23	                           FArray2D<std::complex<double>>& zb) {
24	
25	  // Statement function for pp (others derived by crossing)
26	  auto tree = [&za, &zb](int j1, int j2, int j3, int j4, int j5, int j6) -> std::complex<double> {
27	    return +zb(j1,j2)*za(j5,j4)*(za(j3,j1)*zb(j1,j6)+za(j3,j2)*zb(j2,j6))
28	                /(s(j2,j3)*s(j5,j6)*t(j1,j2,j3))
29	           +za(j3,j4)*zb(j6,j1)*(za(j5,j3)*zb(j3,j2)+za(j5,j4)*zb(j4,j2))
30	                /(s(j2,j3)*s(j5,j6)*t(j2,j3,j4));
31	  };
32	
33	  std::complex<double> result(0.0, 0.0);
34	
35	  if (st[0]=='p' && st[1]=='p') {
36	    result = +tree(j1,j2,j3,j4,j5,j6); // @coverage-probe
37	  } else if (st[0]=='p' && st[1]=='m') {
38	    result = -tree(j1,j3,j2,j4,j5,j6);
39	  } else if (st[0]=='s' && st[1]=='l') {
40	    // Not a real tree amplitude; auxiliary quantity
41	    result = -tree(j3,j1,j2,j4,j5,j6);
42	  }
43	
44	  return result;
45	}
46	
47	extern "C" {
48	  std::complex<double> atree_wrapper(const char* st, int j1, int j2, int j3, int j4, int j5, int j6,
49	                                     std::complex<double>* fza, std::complex<double>* fzb) {
50	    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
51	    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
52	    return atree(st, j1, j2, j3, j4, j5, j6, za, zb);
53	  }
54	}
