3	//
4	//  the matrix elements of the
5	//  helicity amplitudes for the QCD process
6	//  q(-p1)+qbar(-p2) --> l(p3)+abar(p4)+g(p5)+g(p6)
7	//  multiplied by ((a+l)^2-M**2)/(a+l)^2/g^4
8	//  one colour ordering only
9	//  left-on quark line only
10	
11	#include "subqcd.hpp"
12	#include <cmath>
13	#include <complex>
14	#include <constants_mod.hpp>
15	#include <mxpart_mod.hpp>
16	#include <sprods_com_mod.hpp>
17	#include <FArray.hpp>
18	
19	void subqcd(int i1, int i2, int i3, int i4, int i5, int i6,
20	            FArray2D<std::complex<double>>& za,
21	            FArray2D<std::complex<double>>& zb,
22	            FArray2D<std::complex<double>>& amp) {
23	  using namespace constants_mod;
24	  using namespace mxpart_mod;
25	  using namespace sprods_com_mod;
26	
27	  // statement functions translated as lambdas
28	  auto zba2 = [&za, &zb](int i1, int i2, int i3, int i4) -> std::complex<double> {
29	    return zb(i1,i2)*za(i2,i4) + zb(i1,i3)*za(i3,i4);
30	  };
31	
32	  auto zba3 = [&za, &zb](int i1, int i2, int i3, int i4, int i5) -> std::complex<double> {
33	    return zb(i1,i2)*za(i2,i5) + zb(i1,i3)*za(i3,i5) + zb(i1,i4)*za(i4,i5);
34	  };
35	
36	  double s156 = s(i1,i5) + s(i1,i6) + s(i5,i6);
37	  double s256 = s(i2,i5) + s(i2,i6) + s(i5,i6);
38	  double s56 = s(i5,i6);
39	  double s34 = s(i3,i4);
40	  (void)s56;
41	  (void)s34;
42	
43	  amp(-1,-1) = -four/s(i3,i4)
44	    * zb(i1,i4)*zba3(i1,i2,i6,i5,i3)/zb(i1,i5)/zb(i2,i6)/zb(i6,i5);
45	  amp(+1,+1) = +four/s(i3,i4)
46	    * za(i2,i3)*zba3(i4,i1,i6,i5,i2)/za(i1,i5)/za(i2,i6)/za(i6,i5);
47	  amp(+1,-1) = four/(s(i3,i4)*s(i5,i6))
48	    * (zba2(i4,i1,i5,i6)*zba2(i5,i2,i6,i3)/za(i1,i5)/zb(i2,i6)
49	    - za(i1,i6)*za(i2,i3)*zb(i1,i5)*zba2(i4,i1,i5,i6)/za(i1,i5)/s156
50	    - za(i2,i6)*zb(i1,i4)*zb(i2,i5)*zba2(i5,i2,i6,i3)/zb(i2,i6)/s256);
51	  auto _v = four/(s(i3,i4)*s(i5,i6))
52	    * (za(i2,i3)*za(i2,i5)*zb(i1,i4)*zb(i1,i6)/za(i2,i6)/zb(i1,i5)
53	    - za(i2,i3)*std::pow(zb(i1,i6),2)*zba2(i4,i1,i6,i5)/zb(i1,i5)/s156
54	    - std::pow(za(i2,i5),2)*zb(i1,i4)*zba2(i6,i2,i5,i3)/za(i2,i6)/s256);
55	  amp(-1,+1) = _v; // @coverage-probe
56	}
