27	  if (st == hqpgmgpqbm) {
28	    result =
29	        (za(j2,j4)*za(j4,j5)*zb(j1,j3)*zb(j1,j6)) /
30	        (s(j2,j3)*s(j5,j6)*za(j3,j4)*zb(j1,j2))
