32	        (s(j2,j3)*s(j5,j6)*zb(j1,j2)*t(j1,j2,j3))
33	      + (std::pow(za(j2,j4),2)*zb(j1,j6)*(-(za(j2,j5)*zb(j2,j3))+za(j4,j5)*zb(j3,j4))) /
34	        (s(j2,j3)*s(j5,j6)*za(j3,j4)*t(j2,j3,j4));
35	  } else if (st == hqpgpgmqbm) {
36	    result =
37	      - ((za(j3,j5)*zb(j2,j3)+za(j4,j5)*zb(j2,j4)) *
38	         (-(za(j1,j3)*zb(j1,j6))-za(j2,j3)*zb(j2,j6))) /
39	        (s(j2,j3)*s(j5,j6)*za(j1,j2)*zb(j3,j4))
40	      - (za(j1,j3)*za(j4,j5)*zb(j1,j2) *
41	         (-(za(j1,j3)*zb(j1,j6))-za(j2,j3)*zb(j2,j6))) /
