57	        (s(j5,j6)*za(j1,j2)*zb(j1,j4)*t(j1,j2,j4))
58	      - (za(j3,j4)*zb(j1,j6)*(za(j3,j5)*zb(j2,j3)+za(j4,j5)*zb(j2,j4))) /
59	        (s(j5,j6)*za(j2,j3)*zb(j3,j4)*t(j2,j3,j4));
60	  } else if (st == hqpgpqbmgp) {
61	    result =
62	        (-za(j1,j3)*std::pow(za(j3,j5),2)) /
63	        (za(j1,j2)*za(j1,j4)*za(j2,j3)*za(j3,j4)*za(j5,j6));
64	  } else if (st == hqpqbmgmgp) {
65	    result =
66	        ((-(za(j2,j5)*zb(j2,j4))-za(j3,j5)*zb(j3,j4)) *
67	         (-(za(j1,j3)*zb(j1,j6))+za(j3,j4)*zb(j4,j6))) /
